import React from 'react';
import { normalizeAttackName, explainAttackType } from '../utils/helpers';

export function SinglePrediction({ prediction, probability, topClasses }) {
  const predType = prediction;
  const predAttack = normalizeAttackName(predType) !== 'benign' ? 'ATTACK' : 'BENIGN';

  return (
    <div className="card">
      <h3>🧪 Single Record Prediction</h3>
      <p>
        <strong>Predicted:</strong> <code>{predAttack}</code> • 
        <strong> Type:</strong> <code>{predType}</code>
      </p>
      {probability !== null && (
        <p className="caption">P(attack) = {probability.toFixed(3)}</p>
      )}
      {topClasses && (
        <p className="caption">
          Top classes → {topClasses.map(c => `${c.class}: ${c.prob.toFixed(3)}`).join(' | ')}
        </p>
      )}
      {predAttack === 'ATTACK' && (
        <div className="info-box">
          {explainAttackType(predType)}
        </div>
      )}
    </div>
  );
}
